int fast9_corner_score(const byte* p, const int pixel[], int bstart)
{
    const int v = *p;
    short d[25];
    for (int k = 0; k < 16; ++k)
        d[k] = (short)(v - (int)p[pixel[k]]);
    for (int k = 16; k < 25; ++k)
        d[k] = d[k - 16];

    // 暗角点极大连续差值 (Dark corners: v - p[pixel[k]] > threshold)
    int a0 = bstart;
    for (int k = 0; k < 16; k += 2)
    {
        int a = (d[k+1] < d[k+2]) ? d[k+1] : d[k+2];
        a = (a < d[k+3]) ? a : d[k+3];
        if (a <= a0) continue;
        a = (a < d[k+4]) ? a : d[k+4];
        a = (a < d[k+5]) ? a : d[k+5];
        a = (a < d[k+6]) ? a : d[k+6];
        a = (a < d[k+7]) ? a : d[k+7];
        a = (a < d[k+8]) ? a : d[k+8];
        int m0 = (a < d[k]) ? a : d[k];
        if (m0 > a0) a0 = m0;
        int m9 = (a < d[k+9]) ? a : d[k+9];
        if (m9 > a0) a0 = m9;
    }

    // 亮角点极大连续差值 (Bright corners: p[pixel[k]] - v > threshold)
    int b0 = -a0;
    for (int k = 0; k < 16; k += 2)
    {
        int b = (d[k+1] > d[k+2]) ? d[k+1] : d[k+2];
        b = (b > d[k+3]) ? b : d[k+3];
        if (b >= b0) continue;
        b = (b > d[k+4]) ? b : d[k+4];
        b = (b > d[k+5]) ? b : d[k+5];
        b = (b > d[k+6]) ? b : d[k+6];
        b = (b > d[k+7]) ? b : d[k+7];
        b = (b > d[k+8]) ? b : d[k+8];
        int m0 = (b > d[k]) ? b : d[k];
        if (m0 < b0) b0 = m0;
        int m9 = (b > d[k+9]) ? b : d[k+9];
        if (m9 < b0) b0 = m9;
    }

    int score = -b0 - 1;
    return (score >= bstart) ? score : bstart;
}

static void make_offsets(int pixel[], int row_stride)
{
        pixel[0] = 0 + row_stride * 3;
        pixel[1] = 1 + row_stride * 3;
        pixel[2] = 2 + row_stride * 2;
        pixel[3] = 3 + row_stride * 1;
        pixel[4] = 3 + row_stride * 0;
        pixel[5] = 3 + row_stride * -1;
        pixel[6] = 2 + row_stride * -2;
        pixel[7] = 1 + row_stride * -3;
        pixel[8] = 0 + row_stride * -3;
        pixel[9] = -1 + row_stride * -3;
        pixel[10] = -2 + row_stride * -2;
        pixel[11] = -3 + row_stride * -1;
        pixel[12] = -3 + row_stride * 0;
        pixel[13] = -3 + row_stride * 1;
        pixel[14] = -2 + row_stride * 2;
        pixel[15] = -1 + row_stride * 3;
}



int* fast9_score(const byte* i, int stride, xy* corners, int num_corners, int b)
{	
	int* scores = (int*)malloc(sizeof(int)* num_corners);
	int n;

	int pixel[16];
	make_offsets(pixel, stride);

    for(n=0; n < num_corners; n++)
        scores[n] = fast9_corner_score(i + corners[n].y*stride + corners[n].x, pixel, b);

	return scores;
}


